#define RANDOM_MAX 0x7FFFFFFF
static long do_rand(unsigned long *value)
{
	long quotient, remainder, t;
	quotient = *value / 127773L;

	remainder = *value % 127773L;

	t = 16807L * remainder - 2836L * quotient;

	if (t <= 0)
		t += 0x7FFFFFFFL;

	return ((*value = t) % ((unsigned long)RANDOM_MAX + 1));
}

static unsigned long next = 1;

static int rand(void)
{
	return do_rand(&next);
}

static void srand(unsigned int seed)
{
	next = seed;
}

#define rand32() ((unsigned int) rand() | ( (unsigned int) rand() << 16))

#define ULONG_MAX  4294967295UL

#if (ULONG_MAX == 4294967295UL)
    #define rand_ul() rand32()
    #define UL_ONEBITS 0xffffffff
    #define UL_LEN 32
    #define CHECKERBOARD1 0x55555555
    #define CHECKERBOARD2 0xaaaaaaaa
    #define UL_BYTE(x) ((x | x << 8 | x << 16 | x << 24))
#elif (ULONG_MAX == 18446744073709551615ULL)
    #define rand64() (((ul) rand32()) << 32 | ((ul) rand32()))
    #define rand_ul() rand64()
    #define UL_ONEBITS 0xffffffffffffffffUL
    #define UL_LEN 64
    #define CHECKERBOARD1 0x5555555555555555
    #define CHECKERBOARD2 0xaaaaaaaaaaaaaaaa
    #define UL_BYTE(x) (((ul)x | (ul)x<<8 | (ul)x<<16 | (ul)x<<24 | (ul)x<<32 | (ul)x<<40 | (ul)x<<48 | (ul)x<<56))
#else
    #error long on this platform is not 32 or 64 bits
#endif

