static void set_read_phase(u8 phase)
{
	(*(unsigned int*)(READ_PHASE_ADDR)) = ((*(unsigned int*)(READ_PHASE_ADDR)) & 0xffffff00) | phase;
	stage1_delay_us(16);
}

static void set_write_phase(u8 phase)
{
	(*(unsigned int*)(WRITE_PHASE_ADDR)) = ((*(unsigned int*)(WRITE_PHASE_ADDR)) & 0xffff00ff) | (phase<<8);
	stage1_delay_us(16);
}


static int compare_regions(ulv *bufa, ulv *bufb, size_t count) {
    int r = 0;
    size_t i;
    ulv *p1 = bufa;
    ulv *p2 = bufb;
    u8 write_phase_default = (DENALI_CONFIG_PHY[4] >> 8) & 0xFF;
    set_write_phase(write_phase_default);
    for (i = 0; i < count; i++, p1++, p2++)
    {
	
        if (*p1 != *p2)
	{
		r = -1;
		return r;
	}
    }
    r = 0;
    return r;
}

static int test_random_value(ulv *bufa, ulv *bufb, size_t count) {
    ulv *p1 = bufa;
    ulv *p2 = bufb;
    ul j = 0;
    size_t i;

    for (i = 0; i < count; i++) {
        *p1++ = *p2++ = rand_ul();
    }
    return compare_regions(bufa, bufb, count);
}


struct test tests[] = {
    { "Random Value"          , test_random_value }            ,
};


static int memory_test_rd(void)
{
	int i;
	int rr = 0;
	int rr_flag = 0;
	for(i = 0; i < sizeof(tests)/sizeof(struct test); i++)
	{
	rr_flag = tests[i].fp((ulv *)memory_test_buf_a, (ulv *)memory_test_buf_b, MEMORY_TEST_BYTES/sizeof(ulv));
	if (rr_flag == -1)
		{
			return 0;
		}
	}
	return 1;
}

static int memory_test_wr(u8 phase)
{
	int i;
	int rr = 0;
	int rr_flag = 0;
	for(i = 0; i < sizeof(tests)/sizeof(struct test); i++)
	{
	rr_flag = tests[i].fp((ulv *)memory_test_buf_a, (ulv *)memory_test_buf_b, MEMORY_TEST_BYTES/sizeof(ulv));
	set_write_phase(phase);
	if (rr_flag == -1)
		{
			return 0;
		}
	}
	return 1;
}

static short int read_phase_test(void)
{
        u8 read_phase_flash = (DENALI_CONFIG_CTL[81]) & 0xFF;
	u8 phase_start = 0x00;
	u8 phase = phase_start;
	u8 read_phase = 0x00;
	u8 phase_left = 0x00;
	u8 phase_right = 0x00;
	set_read_phase(phase);
	
	if (memory_test_rd() == 1)
	{
	}
	else
	{
		phase = phase + 0x04;
		set_read_phase(phase);
		while (memory_test_rd() == 0)
		{
			phase = phase + 0x04;
			set_read_phase(phase);
			if(phase == 0xfc)
			{
				memtest_printf("Warning: read phase test failed\n");
				set_read_phase(read_phase_flash);
				return -1;
			}
		}
	}
	phase_left = phase;
	
	phase = phase_left + 0x50;
	set_read_phase(phase);
	while (memory_test_rd() == 1) //right_boundry coarse test
	{
		phase = phase + 0x10;
		set_read_phase(phase);
	}
	phase = phase - 0x04;
	set_read_phase(phase);
	while (memory_test_rd() == 0) //right_boundry fine test
	{
		phase = phase - 0x04;
		set_read_phase(phase);
	}
	phase_right = phase;
	if(phase_right<=phase_left){
		memtest_printf("Warning: read phase test failed: phase_right<rise\n");
		set_read_phase(read_phase_flash);
		return -1;
	}
	
	read_phase = (phase_left + phase_right)/2;
	memtest_printf("RD(%x,%x) CT=%x", phase_left, phase_right, read_phase);
	if((phase_right-phase_left)<35){ //35 step = 50deg
		memtest_printf("DDR not stable\n");
		set_read_phase(read_phase);
		return 0;
	}
	set_read_phase(read_phase);
	short int read_out;
	return 1;
}

static short int write_phase_test(void)
{
        u8 write_phase_flash = (DENALI_CONFIG_PHY[4]>>8) & 0xFF;
	u8 phase_start = 0x00;
	u8 phase = phase_start;
	u8 write_phase = 0x00;
	u8 phase_left = 0x00;
	u8 phase_right = 0x00;
	set_write_phase(phase);
	short int write_out;
	
	if (memory_test_wr(phase) == 1)
	{
	}
	else
	{
		phase = phase + 0x04;
		set_write_phase(phase);
		while (memory_test_wr(phase) == 0) //left_boundry windows search forwards
		{
			
			phase = phase + 0x04;
			set_write_phase(phase);
			if(phase == 0xfc)
			{
				memtest_printf("Warning: write phase test failed\n");
				set_write_phase(write_phase_flash);
				return -1;
			}
		}
	}
	phase_left = phase;

	phase = phase_left + 0x50;
	set_write_phase(phase);
	while (memory_test_wr(phase) == 1) //right_boundry coarse test
	{
		phase = phase + 0x10;
		set_write_phase(phase);
	}
	phase = phase - 0x04;
	set_write_phase(phase);
	while (memory_test_wr(phase) == 0) //right_boundry fine test
	{
		phase = phase - 0x04;
		set_write_phase(phase);
	}
	phase_right = phase;
	if(phase_right<=phase_left){
		memtest_printf("Warning: write phase test failed: phase_right<rise\n");
		set_write_phase(write_phase_flash);
		return -1;
	}
	write_phase = (phase_left + phase_right)/2;
	memtest_printf(" WR(%x,%x) CT=%x\n", phase_left, phase_right, write_phase);
	if((phase_right-phase_left)<35){ //35 step = 50deg
		memtest_printf("DDR not stable\n");
		set_write_phase(write_phase);
		return 0;
	}
	set_write_phase(write_phase);
	return 1;
}

void ddr_soft_training(void)
{
#ifdef CONFIG_ENABLE_BBT_SLT_TEST
	int rd=0;
	int wr=0;
	rd=read_phase_test();
	wr=write_phase_test();

	if (rd==1 && wr==1) {
		*(volatile unsigned int *)DDR_PHASE_TEST_RESULT_ADDR = 0;
	} else if (rd<0 || wr<0) {
		*(volatile unsigned int *)DDR_PHASE_TEST_RESULT_ADDR = 2;
	} else {
		*(volatile unsigned int *)DDR_PHASE_TEST_RESULT_ADDR = 1;
	}
#else
	read_phase_test();
	write_phase_test();
#endif
}
